/* Create a new user with the specified name, store it in the list
 * of users (the Users global radix tree), and returns a reference to
 * the structure representing the user.
 *
 * If the user with such name already exists NULL is returned. */
user *ACLCreateUser(const char *name, size_t namelen) {
    if (Users->numele > 0 &&
        raxFind(Users,(unsigned char*)name,namelen) != raxNotFound)
    {
        return NULL;
    }
    user *u = zmalloc(sizeof(*u));
    u->flags = USER_FLAG_DISABLED;

    aclSelector *s = zmalloc(sizeof(*s));
    s->flags = SELECTOR_FLAG_ROOT | server.acl_pubsub_default;
    s->patterns = listCreate();
    s->channels = listCreate();
    s->allowed_firstargs = NULL;
    memset(s->allowed_commands,0,sizeof(s->allowed_commands));
    listSetMatchMethod(s->patterns,ACLListMatchKeyPattern);
    listSetFreeMethod(s->patterns,ACLListFreeKeyPattern);
    listSetDupMethod(s->patterns,ACLListDupKeyPattern);
    listSetMatchMethod(s->channels,ACLListMatchSds);
    listSetFreeMethod(s->channels,ACLListFreeSds);
    listSetDupMethod(s->channels,ACLListDupSds);

    listNode *node = zmalloc(sizeof(*node));
    node->value = s;
    ACLRegisterNewUser(u,name,namelen,node);
    return u;
}

/* This function should be called when we need an unlinked "fake" user
 * we can use in order to validate ACL rules or for other similar reasons.
 * The user will not get linked to the Users radix tree. The returned
 * user should be released with ACLFreeUser() as usually. */
user *ACLCreateUnlinkedUser(void) {
    char username[64];
    for (int j = 0; ; j++) {
        snprintf(username,sizeof(username),"__fakeuser:%d__",j);
        user *fakeuser = ACLCreateUser(username,strlen(username));
